log = open('/home/ubuntu/.agent-ml-research-idea_gen_0514_2/projects/persuasion_turn_jailbreak_detect/docs/paper/main.log', 'rb').read()
non_utf8_positions = []
i = 0
while i < len(log):
    b = log[i]
    if b <= 0x7f:
        i += 1
    elif 0xc0 <= b <= 0xdf:
        if i+1 < len(log) and 0x80 <= log[i+1] <= 0xbf:
            i += 2
        else:
            non_utf8_positions.append((i, b))
            i += 1
    elif 0xe0 <= b <= 0xef:
        if i+2 < len(log) and 0x80 <= log[i+1] <= 0xbf and 0x80 <= log[i+2] <= 0xbf:
            i += 3
        else:
            non_utf8_positions.append((i, b))
            i += 1
    elif 0xf0 <= b <= 0xf7:
        if i+3 < len(log) and all(0x80 <= log[i+j] <= 0xbf for j in range(1,4)):
            i += 4
        else:
            non_utf8_positions.append((i, b))
            i += 1
    else:
        non_utf8_positions.append((i, b))
        i += 1

print(f'Total non-UTF-8 bytes: {len(non_utf8_positions)}')
for pos, b in non_utf8_positions[:20]:
    line = log[:pos].count(b'\n') + 1
    ctx = log[max(0,pos-15):pos+15]
    print(f'  line {line}, pos {pos}, byte 0x{b:02x}, context: {repr(ctx)}')
"

